def write_json(path, value, canonical=False):
    path.parent.mkdir(parents=True, exist_ok=True)
    path.write_bytes(web.canonical_json_bytes(value) if canonical else (json.dumps(value, indent=2, sort_keys=True)+"\n").encode())


def legacy_signal(bright=100, dark=100, luma=50.0, band=True, visible=True):
    return {"bright_center_pixels":bright,"corner_luma":luma,"dark_center_pixels":dark,"dimensions":[1280,720],"title_background_band":band,"visible":visible}


