def assert_code(test, expected, call, fixture=None):
    with test.assertRaises(web.ContractError) as raised: call()
    actual = raised.exception.code
    test.assertEqual(actual, expected)
    if fixture is not None:
        test.observe(fixture, actual)
    return actual


def generation_option_values(tree, out, start_path):
    values = {
        "--repo":tree.repo,"--out":out,"--candidate":tree.candidate,"--tree":tree.tree,
        "--run-receipt":start_path,"--run-receipt-sha256":web.sha256(start_path),
        "--owner-decision":tree.args.owner_decision,"--owner-decision-sha256":web.OWNER_DECISION_SHA256,
        "--palette-contract":tree.args.palette_contract,"--oracle-contract":tree.args.oracle_contract,
        "--oracle-sha256":web.ORACLE_SHA256,"--approval-manifest":tree.args.approval_manifest,
        "--approval-manifest-sha256":web.APPROVAL_MANIFEST_SHA256,
        "--owner-decision-schema":tree.args.owner_decision_schema,
        "--owner-decision-schema-sha256":web.OWNER_DECISION_SCHEMA_SHA256,
        "--start-receipt-schema":tree.args.start_receipt_schema,
        "--start-receipt-schema-sha256":web.START_RECEIPT_SCHEMA_SHA256,
        "--completion-receipt-schema":tree.args.completion_receipt_schema,
        "--completion-receipt-schema-sha256":web.COMPLETION_RECEIPT_SCHEMA_SHA256,
        "--transcript-schema":tree.args.transcript_schema,
        "--transcript-schema-sha256":web.TRANSCRIPT_SCHEMA_SHA256,
        "--legacy-schema":tree.args.legacy_schema,"--legacy-schema-sha256":web.LEGACY_SCHEMA_SHA256,
        "--contract-schema":tree.args.contract_schema,"--contract-schema-sha256":web.CONTRACT_SCHEMA_SHA256,
    }
    assert set(values) == set(web.GENERATION_REQUIRED_OPTIONS)
    return values


def generation_argv(tree, out, start_path):
    values = generation_option_values(tree, out, start_path)
    return [part for option in web.GENERATION_REQUIRED_OPTIONS for part in (option, str(values[option]))]


